namespace CheckoutPricing.Domain;

public static class LoyaltyDiscountPolicy
{
    private const int MinimumSubtotalCents = 3_000;
    private const int CapCents = 2_000;

    public static int LoyaltyPartCents(int subtotalCents, LoyaltyTier tier) =>
        subtotalCents < MinimumSubtotalCents
            ? 0
            : Math.Min(CapCents, subtotalCents * RatePercent(tier) / 100);

    private static int RatePercent(LoyaltyTier tier) => tier switch
    {
        LoyaltyTier.Bronze => 5,
        LoyaltyTier.Silver => 10,
        LoyaltyTier.Gold => 15,
        LoyaltyTier.Platinum => 20,
        _ => throw new ArgumentOutOfRangeException(nameof(tier))
    };
}
E
cat > $D/PromoCodePolicy.cs <<'E'
namespace CheckoutPricing.Domain;

public static class PromoCodePolicy
{
    private const int Welcome5Cents = 500;
    private const int Summer10CapCents = 1_500;

    public static int PromoPartCents(string? code, int subtotalCents, int loyaltyPartCents)
    {
        if (string.Equals(code, "WELCOME5", StringComparison.OrdinalIgnoreCase))
        {
            return Welcome5Cents;
        }

        if (string.Equals(code, "SUMMER10", StringComparison.OrdinalIgnoreCase))
        {
            return Math.Min(Summer10CapCents, (subtotalCents - loyaltyPartCents) / 10);
        }

        return 0;
    }
}
E
cat > $D/DiscountPolicy.cs <<'E'
namespace CheckoutPricing.Domain;

public static class DiscountPolicy
{
    public static int DiscountCents(int subtotalCents, LoyaltyTier tier, string? promoCode)
    {
        var loyaltyPart = LoyaltyDiscountPolicy.LoyaltyPartCents(subtotalCents, tier);
        var promoPart = PromoCodePolicy.PromoPartCents(promoCode, subtotalCents, loyaltyPart);
        return Math.Min(subtotalCents, loyaltyPart + promoPart);
    }
}
E
